Contract CoCoMEOrderProducts::makeNewOrder(orderid:Integer): Boolean {

            precondition:
          OrderProduct.allInstances()->forAll(o: OrderProduct | o.orderid <> orderid)

            postcondition:
          result = true and CurrentOrderProduct.oclIsNew() and OrderProduct.allInstances()->includes(CurrentOrderProduct) and CurrentOrderProduct.orderid = orderid and CurrentOrderProduct.status = "NEW" and CurrentOrderProduct.Time = Now

        }
